// Pulls the release notes and version number into the docs site at build time.
//
// CHANGELOG.md is generated by release-please at the repo root; duplicating it
// by hand would guarantee it goes stale. Both outputs are gitignored and
// regenerated by `npm run build` / `npm run dev` (see the prebuild scripts).
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = join(here, "..", "..");

const version = JSON.parse(
  readFileSync(join(repoRoot, ".release-please-manifest.json"), "utf8"),
)["."];

const changelog = readFileSync(join(repoRoot, "CHANGELOG.md"), "utf8")
  // The file leads with its own "# Changelog" heading; the page frontmatter
  // supplies the title, so drop it to avoid two <h1>s.
  .replace(/^# Changelog\n+/, "");

const frontmatter = `---
title: Release Notes
description: Every released version of MC GamerTime, with the changes in each.
sidebar:
  order: 9
  badge:
    text: v${version}
    variant: note
---

<!--
  Generated from CHANGELOG.md by docs-site/scripts/sync-release-info.mjs on
  every build. Edits here are overwritten; change CHANGELOG.md instead.
  Kept as a comment rather than a callout: readers of this page want the
  release notes, not a note about how the page is produced.
-->

`;

const outDir = join(here, "..", "src", "content", "docs", "self-hosting");
mkdirSync(outDir, { recursive: true });
// Plain Markdown, not MDX: the changelog contains `{pk}` and similar braces
// that MDX would try to evaluate as JavaScript expressions.
writeFileSync(join(outDir, "release-notes.md"), frontmatter + changelog);
writeFileSync(join(here, "..", "src", "version.json"), JSON.stringify({ version }, null, 2) + "\n");

console.log(`sync-release-info: v${version}, ${changelog.length} bytes of changelog`);
